<?php
require_once 'auth_check.php';require_once '../koneksi.php';require_once 'app_helpers.php';$role=$_SESSION['kode_role'];if(!in_array($role,['ADMIN','OPERATOR_PRODI'],true)){http_response_code(403);die('403 - Akses ditolak.');}$id=get_id();if(!$id)redirect_to('mahasiswa.php');$stmt=mysqli_prepare($koneksi,"SELECT * FROM mahasiswa WHERE id_mahasiswa=?");mysqli_stmt_bind_param($stmt,'i',$id);mysqli_stmt_execute($stmt);$r=mysqli_fetch_assoc(mysqli_stmt_get_result($stmt));mysqli_stmt_close($stmt);if(!$r)die('Data mahasiswa tidak ditemukan.');if($role==='OPERATOR_PRODI'&&(int)$r['id_program_studi']!==(int)$_SESSION['id_program_studi']){http_response_code(403);die('403 - Data di luar kewenangan.');}$prodis=[];$res=mysqli_query($koneksi,"SELECT ps.id_program_studi,ps.nama_program_studi,f.nama_fakultas FROM program_studi ps JOIN fakultas f ON ps.id_fakultas=f.id_fakultas WHERE ps.status_aktif='Aktif' ORDER BY f.nama_fakultas,ps.nama_program_studi");while($x=mysqli_fetch_assoc($res))$prodis[]=$x;$error='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_verify();$old=$r;$fields=['npm','nama_mahasiswa','jenis_kelamin','tempat_lahir','tanggal_lahir','tanggal_masuk','alamat','status_mahasiswa'];foreach($fields as $f)$r[$f]=trim($_POST[$f]??'');$r['id_program_studi']=(int)($_POST['id_program_studi']??$r['id_program_studi']);if($role==='OPERATOR_PRODI')$r['id_program_studi']=(int)$_SESSION['id_program_studi'];if($r['npm']===''||$r['nama_mahasiswa']===''||!$r['id_program_studi']||$r['tanggal_masuk']==='')$error='NPM, nama, prodi, dan tanggal masuk wajib diisi.';if(!$error){$st=mysqli_prepare($koneksi,"UPDATE mahasiswa SET id_program_studi=?,npm=?,nama_mahasiswa=?,jenis_kelamin=?,tempat_lahir=?,tanggal_lahir=?,tanggal_masuk=?,alamat=?,status_mahasiswa=? WHERE id_mahasiswa=?");mysqli_stmt_bind_param($st,'issssssssi',$r['id_program_studi'],$r['npm'],$r['nama_mahasiswa'],$r['jenis_kelamin'],$r['tempat_lahir'],$r['tanggal_lahir'],$r['tanggal_masuk'],$r['alamat'],$r['status_mahasiswa'],$id);if(mysqli_stmt_execute($st)){audit_log($koneksi,(int)$_SESSION['id_pengguna'],'mahasiswa',(string)$id,'UPDATE',$old,$r);flash('success','Data mahasiswa berhasil diperbarui.');redirect_to('mahasiswa.php');}$error='Gagal memperbarui: '.mysqli_stmt_error($st);mysqli_stmt_close($st);}}
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Edit Mahasiswa</title><link rel="stylesheet" href="style.css"></head><body class="app-body"><?php include 'topbar.php';include 'sideleftbar.php';?><main class="main-content"><div class="page-heading"><span class="eyebrow">DATA AKADEMIK</span><h1>Edit Mahasiswa</h1></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="dashboard-panel form-panel"><form method="post"><div class="form-grid"><?php foreach([['npm','NPM'],['nama_mahasiswa','Nama Mahasiswa'],['tempat_lahir','Tempat Lahir']] as [$n,$l]):?><div class="form-group"><label><?=$l?></label><input name="<?=$n?>" value="<?=e($r[$n])?>" required></div><?php endforeach;?><div class="form-group"><label>Program Studi</label><select name="id_program_studi" <?php if($role==='OPERATOR_PRODI')echo'disabled';?>><?php foreach($prodis as $p):?><option value="<?=$p['id_program_studi']?>" <?=$r['id_program_studi']==$p['id_program_studi']?'selected':''?>><?=e($p['nama_fakultas'].' - '.$p['nama_program_studi'])?></option><?php endforeach;?></select><?php if($role==='OPERATOR_PRODI'):?><input type="hidden" name="id_program_studi" value="<?=$r['id_program_studi']?>"><?php endif;?></div><div class="form-group"><label>Jenis Kelamin</label><select name="jenis_kelamin"><option value="L" <?=$r['jenis_kelamin']==='L'?'selected':''?>>Laki-laki</option><option value="P" <?=$r['jenis_kelamin']==='P'?'selected':''?>>Perempuan</option></select></div><div class="form-group"><label>Tanggal Lahir</label><input type="date" name="tanggal_lahir" value="<?=e($r['tanggal_lahir'])?>"></div><div class="form-group"><label>Tanggal Masuk</label><input type="date" name="tanggal_masuk" required value="<?=e($r['tanggal_masuk'])?>"></div><div class="form-group"><label>Status</label><select name="status_mahasiswa"><?php foreach(['Aktif','Cuti','Lulus','Mengundurkan Diri','Drop Out','Tidak Aktif'] as $s):?><option <?=$r['status_mahasiswa']===$s?'selected':''?>><?=e($s)?></option><?php endforeach;?></select></div></div><div class="form-group"><label>Alamat</label><textarea name="alamat" rows="4"><?=e($r['alamat'])?></textarea></div><div class="form-actions"><a class="btn btn-outline" href="mahasiswa.php">Batal</a><button class="btn btn-primary">Simpan Perubahan</button></div></form></div></main><script src="script.js"></script></body></html>